package edu.cybertrace;
import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import org.springframework.http.*; import org.springframework.web.server.ResponseStatusException; import org.springframework.security.core.Authentication; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.transaction.annotation.Transactional;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.security.authentication.AuthenticationManager; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContext; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.web.context.SecurityContextRepository; import org.springframework.security.web.authentication.logout.SecurityContextLogoutHandler; import org.springframework.security.web.csrf.CsrfTokenRepository; import jakarta.servlet.http.HttpServletRequest; import jakarta.servlet.http.HttpServletResponse;
import java.nio.file.*; import java.time.Instant; import java.util.*; import java.nio.charset.StandardCharsets;
@RestController @RequestMapping("/api") class Api {
 @Value("${cybertrace.storage:../storage/evidence}") String storageDirectory;
 @Value("${CYBERTRACE_SETUP_TOKEN:}") String setupToken;
 final Users users;final EvidenceRepo evidence;final EvidenceVersionRepo versions;final CustodyRepo custody;final VerificationRepo verifications;final AuditRepo audits;final AlertRepo alerts;final CaseRepo cases;final CaseShareRepo shares;final CaseNoteRepo caseNotes;final SystemSettingRepo settings;final ForensicsService service;final PasswordEncoder encoder;final AuthenticationManager authenticationManager;final SecurityContextRepository contextRepository;final CsrfTokenRepository csrfTokens;
 Api(Users u,EvidenceRepo e,EvidenceVersionRepo ev,CustodyRepo c,VerificationRepo v,AuditRepo a,AlertRepo al,CaseRepo cr,CaseShareRepo sh,CaseNoteRepo cn,SystemSettingRepo settings,ForensicsService s,PasswordEncoder pe,AuthenticationManager am,SecurityContextRepository sc,CsrfTokenRepository csrfTokens){users=u;evidence=e;versions=ev;custody=c;verifications=v;audits=a;alerts=al;cases=cr;shares=sh;caseNotes=cn;this.settings=settings;service=s;encoder=pe;authenticationManager=am;contextRepository=sc;this.csrfTokens=csrfTokens;}
 @PostMapping("/auth/register") @Transactional Map<String,Object> register(@RequestBody Map<String,String> b){boolean bootstrapped=settings.findById("ADMIN_BOOTSTRAP_COMPLETE").map(x->Boolean.parseBoolean(x.settingValue)).orElse(false)||users.existsByRole(RolePolicy.ADMIN);if(!bootstrapped){if(setupToken==null||setupToken.isBlank()||!constantTimeEquals(setupToken,b.get("setupToken")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Initial administrator setup requires the one-time setup key configured by the server administrator");Map<String,Object> created=createUser(b,RolePolicy.ADMIN,"One-time protected administrator bootstrap");settings.save(new SystemSetting("ADMIN_BOOTSTRAP_COMPLETE","true"));return created;}return createUser(b,RolePolicy.RECIPIENT,"Public registration; read-only external reviewer");}
 boolean constantTimeEquals(String expected,String provided){return provided!=null&&java.security.MessageDigest.isEqual(expected.getBytes(StandardCharsets.UTF_8),provided.getBytes(StandardCharsets.UTF_8));}
 @PostMapping("/auth/login") Map<String,Object> login(@RequestBody Map<String,String> b,HttpServletRequest request,HttpServletResponse response){String username=Objects.toString(b.get("username"),"");try{var auth=authenticationManager.authenticate(UsernamePasswordAuthenticationToken.unauthenticated(username,Objects.toString(b.get("password"),"")));var existing=request.getSession(false);if(existing!=null)existing.invalidate();request.getSession(true);csrfTokens.saveToken(null,request,response);SecurityContext context=SecurityContextHolder.createEmptyContext();context.setAuthentication(auth);SecurityContextHolder.setContext(context);contextRepository.saveContext(context,request,response);service.audit(username,"LOGIN","user:"+username,"SUCCESS","Session established");return Map.of("username",username,"role",users.findByUsername(username).orElseThrow().role);}catch(org.springframework.security.core.AuthenticationException ex){throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Username or password is incorrect");}}
 @PostMapping("/auth/logout") ResponseEntity<Void> logout(Authentication a,HttpServletRequest request,HttpServletResponse response){if(a!=null&&a.isAuthenticated())service.audit(a.getName(),"LOGOUT","user:"+a.getName(),"SUCCESS","Session ended");new SecurityContextLogoutHandler().logout(request,response,a);return ResponseEntity.noContent().build();}
 @GetMapping("/auth/setup-status") Map<String,Object> setupStatus(){boolean complete=settings.findById("ADMIN_BOOTSTRAP_COMPLETE").map(x->Boolean.parseBoolean(x.settingValue)).orElse(false)||users.existsByRole(RolePolicy.ADMIN);return Map.of("adminReady",complete);}
 @GetMapping("/auth/csrf") Map<String,String> csrf(org.springframework.security.web.csrf.CsrfToken token){return Map.of("token",token.getToken());}
 @PostMapping("/users") Map<String,Object> createUser(@RequestBody Map<String,String>b,Authentication a){if(!role(a,"ADMIN"))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return createUser(b,b.getOrDefault("role","INVESTIGATOR"),"Account created by "+a.getName());}
 Map<String,Object> createUser(Map<String,String>b,String requested,String details){String name=b.get("username"),pass=b.get("password");if(name==null||name.length()<3||pass==null||pass.length()<10)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Username must have 3+ characters and password 10+ characters");if(!RolePolicy.APPROVED.contains(requested))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid role");Optional<UserRecord> old=users.findByUsername(name);if(old.isPresent()&&old.get().enabled)throw new ResponseStatusException(HttpStatus.CONFLICT,"That username is already active");UserRecord u=old.orElseGet(UserRecord::new);u.username=name;u.password=encoder.encode(pass);u.role=requested;u.enabled=true;users.save(u);service.audit(name,old.isPresent()?"ACCOUNT_REACTIVATE":"ACCOUNT_CREATE","user:"+name,"SUCCESS",details+"; role="+requested);return Map.of("username",name,"role",u.role);}
 @GetMapping("/auth/me") Map<String,Object> me(Authentication a){var u=users.findByUsername(a.getName()).orElseThrow();return Map.of("username",u.username,"role",u.role);}
 @GetMapping("/dashboard") Map<String,Object> dashboard(Authentication a){List<Evidence> visible=evidence.findAll().stream().filter(e->canViewEvidence(e,a)).toList();Set<String> visibleCases=new HashSet<>();cases.findAll().stream().filter(c->canViewCase(c,a)).forEach(c->visibleCases.add(c.caseNo));List<Custody> visibleCustody=custody.findAll().stream().filter(c->visible.stream().anyMatch(e->Objects.equals(e.id,c.evidenceId))).toList();return Map.of("evidenceCount",visible.size(),"verifiedCount",visible.stream().filter(e->"INTACT".equals(e.lastIntegrityStatus)).count(),"mismatchCount",visible.stream().filter(e->"MODIFIED".equals(e.lastIntegrityStatus)).count(),"activeCases",cases.findAll().stream().filter(c->visibleCases.contains(c.caseNo)&&!"CLOSED".equals(c.status)).count(),"pendingTransfers",visibleCustody.stream().filter(c->"REQUESTED".equals(c.status)).count(),"unreadAlerts",alerts.findAllByOrderByIdDesc().stream().filter(x->x.unread&&(role(a,"ADMIN")||a.getName().equals(x.owner))).count(),"recentEvidence",visible.stream().sorted(Comparator.comparing((Evidence e)->e.uploadedAt,Comparator.nullsLast(Comparator.reverseOrder()))).limit(5).toList(),"recentCustody",visibleCustody.stream().sorted(Comparator.comparing((Custody c)->c.requestedAt,Comparator.nullsLast(Comparator.reverseOrder()))).limit(5).toList(),"upcomingHearings",cases.findAll().stream().filter(c->visibleCases.contains(c.caseNo)&&c.hearingDate!=null&&!c.hearingDate.isBefore(java.time.LocalDate.now())).sorted(Comparator.comparing(c->c.hearingDate)).limit(5).toList());}
 @GetMapping("/cases") List<CaseRecord> listCases(Authentication a){return cases.findAll().stream().filter(c->canViewCase(c,a)).toList();}
 @PostMapping("/cases") CaseRecord createCase(@RequestBody Map<String,String>b,Authentication a){if(!role(a,RolePolicy.ADMIN,RolePolicy.INVESTIGATOR))throw new ResponseStatusException(HttpStatus.FORBIDDEN);String no=b.get("caseNo"),title=b.get("title");if(no==null||no.isBlank()||title==null||title.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Case number and title are required");if(cases.findAll().stream().anyMatch(c->c.caseNo.equals(no)))throw new ResponseStatusException(HttpStatus.CONFLICT,"That case number is already registered");CaseRecord c=new CaseRecord();c.caseNo=no;c.title=title;c.description=b.get("description");c.assignedTo=Objects.toString(b.get("assignedTo"),a.getName());if(!Objects.equals(c.assignedTo,a.getName())&&users.findByUsername(c.assignedTo).filter(u->u.enabled&&Set.of(RolePolicy.ADMIN,RolePolicy.INVESTIGATOR).contains(u.role)).isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Assign the case to an active investigator");c.createdBy=a.getName();c.createdAt=Instant.now();c.status="OPEN";c.hearingDate=parseDate(b.get("hearingDate"));c.investigationDueDate=parseDate(b.get("investigationDueDate"));cases.save(c);service.audit(a.getName(),"CASE_CREATE",no,"SUCCESS",title+"; assigned to="+c.assignedTo);return c;}
 @PostMapping("/cases/{id}/share") Map<String,Object> shareCase(@PathVariable long id,@RequestBody Map<String,String>b,Authentication a){CaseRecord c=cases.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Case not found"));if(!(role(a,RolePolicy.ADMIN)||role(a,RolePolicy.INVESTIGATOR)&&Objects.equals(c.assignedTo,a.getName())))throw new ResponseStatusException(HttpStatus.FORBIDDEN);String username=b.get("username");UserRecord user=users.findByUsername(username).filter(u->u.enabled).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Active account not found"));if(!shares.existsByCaseIdAndUsername(id,username)){CaseShare x=new CaseShare();x.caseId=id;x.username=username;x.sharedBy=a.getName();x.sharedAt=Instant.now();shares.save(x);}service.audit(a.getName(),"CASE_SHARE",c.caseNo,"SUCCESS","Read-only access shared with "+username);return Map.of("caseNo",c.caseNo,"sharedWith",username);}
 @PatchMapping("/cases/{id}") CaseRecord updateCase(@PathVariable long id,@RequestBody Map<String,String>b,Authentication a){CaseRecord c=cases.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Case not found"));if(!(role(a,RolePolicy.ADMIN)||role(a,RolePolicy.INVESTIGATOR)&&Objects.equals(c.assignedTo,a.getName())))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the assigned investigator or administrator may update case status");String old=c.status;if(b.containsKey("status")){String next=b.get("status");if(!Set.of("OPEN","UNDER_INVESTIGATION","PENDING_COURT","CLOSED").contains(next))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid case status");c.status=next;}if(b.containsKey("description"))c.description=b.get("description");if(b.containsKey("hearingDate"))c.hearingDate=parseDate(b.get("hearingDate"));if(b.containsKey("investigationDueDate"))c.investigationDueDate=parseDate(b.get("investigationDueDate"));cases.save(c);service.audit(a.getName(),"CASE_UPDATE",c.caseNo,"SUCCESS","status="+old+" -> "+c.status);return c;}
 @GetMapping("/cases/{id}/notes") List<CaseNote> listCaseNotes(@PathVariable long id,Authentication a){CaseRecord c=cases.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Case not found"));if(!canViewCase(c,a))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return caseNotes.findByCaseIdOrderByIdAsc(id);}
 @PostMapping("/cases/{id}/notes") CaseNote addCaseNote(@PathVariable long id,@RequestBody Map<String,String>b,Authentication a){CaseRecord c=cases.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Case not found"));boolean officer=role(a,RolePolicy.ADMIN)||role(a,RolePolicy.INVESTIGATOR)&&Objects.equals(c.assignedTo,a.getName());boolean reviewer=role(a,RolePolicy.COURT)&&shares.existsByCaseIdAndUsername(id,a.getName());if(!officer&&!reviewer)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the assigned officer or a shared judicial reviewer may add a note");String body=Objects.toString(b.get("body"),"").trim();if(body.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Note text is required");CaseNote note=new CaseNote();note.caseId=id;note.author=a.getName();note.authorRole=users.findByUsername(a.getName()).orElseThrow().role;note.noteType=role(a,RolePolicy.COURT)?"JUDICIAL_REVIEW":"INVESTIGATION";note.body=body;note.createdAt=Instant.now();caseNotes.save(note);service.audit(a.getName(),"CASE_NOTE_ADD",c.caseNo,"SUCCESS",note.noteType);return note;}
 java.time.LocalDate parseDate(String text){if(text==null||text.isBlank())return null;try{return java.time.LocalDate.parse(text);}catch(Exception ex){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Dates must use YYYY-MM-DD format");}}
 boolean canViewCase(CaseRecord c,Authentication a){return role(a,RolePolicy.ADMIN)||Objects.equals(c.createdBy,a.getName())||Objects.equals(c.assignedTo,a.getName())||shares.existsByCaseIdAndUsername(c.id,a.getName());}
 boolean canViewEvidence(Evidence e,Authentication a){if(role(a,RolePolicy.ADMIN)||Objects.equals(e.registeredBy,a.getName())||Objects.equals(e.custodian,a.getName()))return true;if(e.caseNo==null)return false;return cases.findAll().stream().filter(c->Objects.equals(c.caseNo,e.caseNo)).anyMatch(c->canViewCase(c,a));}
 boolean canEditMetadata(Evidence e,Authentication a){return role(a,RolePolicy.ADMIN)||(role(a,RolePolicy.LAWYER)&&Objects.equals(e.registeredBy,a.getName()));}
 boolean canSubmitVersion(Evidence e,Authentication a){return canEditMetadata(e,a);}
 @GetMapping("/users") List<Map<String,Object>> listUsers(Authentication a){if(!role(a,"ADMIN"))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return users.findAll().stream().map(u->Map.<String,Object>of("id",u.id,"username",u.username,"role",u.role,"enabled",u.enabled)).toList();}
 @PutMapping("/users/{id}/role") Map<String,Object> changeRole(@PathVariable long id,@RequestBody Map<String,String>b,Authentication a){if(!role(a,RolePolicy.ADMIN))throw new ResponseStatusException(HttpStatus.FORBIDDEN);UserRecord u=users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));String newRole=b.get("role");if(newRole==null||!RolePolicy.APPROVED.contains(newRole))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid role");if(u.enabled&&RolePolicy.ADMIN.equals(u.role)&&!RolePolicy.ADMIN.equals(newRole)&&users.findAll().stream().filter(x->x.enabled&&RolePolicy.ADMIN.equals(x.role)).count()<=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"Assign another administrator before changing the last administrator role");String before=u.role;u.role=newRole;users.save(u);service.audit(a.getName(),"ROLE_CHANGE","user:"+u.username,"SUCCESS",before+" -> "+newRole);return Map.of("username",u.username,"role",u.role);}
 @DeleteMapping("/users/{id}") ResponseEntity<?> deactivateUser(@PathVariable long id,Authentication a){if(!role(a,RolePolicy.ADMIN))throw new ResponseStatusException(HttpStatus.FORBIDDEN);UserRecord user=users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(Objects.equals(user.username,a.getName()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"You cannot deactivate your own signed-in account");if(user.enabled&&RolePolicy.ADMIN.equals(user.role)&&users.findAll().stream().filter(u->u.enabled&&RolePolicy.ADMIN.equals(u.role)).count()<=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"Create another administrator before deactivating the last active administrator");user.enabled=false;users.save(user);service.audit(a.getName(),"ACCOUNT_DEACTIVATE","user:"+user.username,"SUCCESS","Account disabled; historical records retained");return ResponseEntity.noContent().build();}
 @PostMapping("/evidence") @Transactional Evidence upload(@RequestParam MultipartFile file,@RequestParam String category,@RequestParam(required=false) String description,@RequestParam String caseNo,@RequestParam(required=false) String investigationRef,@RequestParam(required=false) String source,@RequestParam(required=false) String reason,@RequestParam(required=false) String collectedAt,Authentication auth)throws Exception{
 if(!role(auth,RolePolicy.ADMIN,RolePolicy.INVESTIGATOR,RolePolicy.LAWYER))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only authorized case staff can register evidence");if(caseNo==null||caseNo.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Evidence must be registered to a case");CaseRecord targetCase=cases.findByCaseNo(caseNo).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Case not found"));if(!canViewCase(targetCase,auth))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"This account is not authorized for that case");
 if(file.isEmpty()||file.getSize()>25L*1024*1024)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"File must be non-empty and at most 25 MB");String original=Objects.requireNonNullElse(file.getOriginalFilename(),"upload");String ext=extension(original);Path dir=storageDir();Files.createDirectories(dir);String storage=UUID.randomUUID()+"."+ext;Path dst=dir.resolve(storage).normalize();file.transferTo(dst);Evidence x=new Evidence();x.filename=Path.of(original).getFileName().toString();x.storageName=storage;x.category=category;x.description=description;x.caseNo=caseNo;x.investigationRef=investigationRef;x.source=source;x.reason=reason;x.registeredBy=auth.getName();x.custodian=auth.getName();x.mimeType=Objects.requireNonNullElse(file.getContentType(),"application/octet-stream");x.size=Files.size(dst);x.referenceHash=ForensicsService.hash(dst);x.lastObservedHash=x.referenceHash;x.lastIntegrityStatus="INTACT";x.lastCheckedAt=Instant.now();x.uploadedAt=Instant.now();x.collectedAt=collectedAt==null?Instant.now():Instant.parse(collectedAt);evidence.saveAndFlush(x);x.evidenceNo=String.format("EV-%d-%04d",x.uploadedAt.atZone(java.time.ZoneOffset.UTC).getYear(),x.id);recordVersion(x,auth.getName(),"Original evidence registration");service.audit(auth.getName(),"EVIDENCE_REGISTER",x.evidenceNo,"SUCCESS","SHA-256="+x.referenceHash);return x;}
 Path storageDir(){return Path.of(storageDirectory).toAbsolutePath().normalize();}
 String extension(String name){int dot=name.lastIndexOf('.');String ext=dot<0?"":name.substring(dot+1).toLowerCase(Locale.ROOT);if(!Set.of("pdf","doc","docx","txt","rtf","odt","xls","xlsx","csv","ppt","pptx","jpg","jpeg","png","gif","webp").contains(ext))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported file type");return ext;}
 void recordVersion(Evidence e,String actor,String note)throws Exception{EvidenceVersion v=new EvidenceVersion();v.evidenceId=e.id;v.versionNumber=versions.findByEvidenceIdOrderByVersionNumberDesc(e.id).stream().mapToInt(x->x.versionNumber).max().orElse(0)+1;v.storageName=e.storageName;v.sha256=ForensicsService.hash(storageDir().resolve(e.storageName));v.filename=e.filename;v.changedBy=actor;v.note=note;v.createdAt=Instant.now();versions.save(v);}
 @GetMapping("/evidence") List<Evidence> list(Authentication a){return evidence.findAll().stream().filter(e->canViewEvidence(e,a)).toList();}
 Evidence get(long id){return evidence.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Evidence not found"));}
 @GetMapping("/evidence/{id}") Evidence detail(@PathVariable String id,Authentication a){Evidence e=get(parse(id));if(!canViewEvidence(e,a))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return e;}
 @PatchMapping("/evidence/{id}") Evidence updateEvidence(@PathVariable String id,@RequestBody Map<String,String>b,Authentication a){Evidence e=get(parse(id));if(!canEditMetadata(e,a)){blockedChange(e,a,"EVIDENCE_METADATA_EDIT");throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the registering officer, assigned investigator, or admin may edit case metadata");}String before="category="+e.category+"; case="+e.caseNo+"; description="+e.description;e.category=b.getOrDefault("category",e.category);e.description=b.getOrDefault("description",e.description);e.caseNo=b.getOrDefault("caseNo",e.caseNo);e.investigationRef=b.getOrDefault("investigationRef",e.investigationRef);e.source=b.getOrDefault("source",e.source);e.reason=b.getOrDefault("reason",e.reason);evidence.save(e);service.audit(a.getName(),"EVIDENCE_METADATA_EDIT",e.evidenceNo,"SUCCESS",before+" -> category="+e.category+"; case="+e.caseNo+"; description="+e.description);if(!a.getName().equals(e.registeredBy))service.alert("MEDIUM","Evidence metadata changed by "+a.getName(),e.id,a.getName(),e.registeredBy);return e;}
 @PostMapping(value="/evidence/{id}/versions",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) EvidenceVersion uploadVersion(@PathVariable String id,@RequestParam MultipartFile file,@RequestParam(required=false) String note,Authentication a)throws Exception{Evidence e=get(parse(id));if(!canSubmitVersion(e,a)){blockedChange(e,a,"EVIDENCE_FILE_CHANGE");throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Read-only or unassigned accounts cannot change evidence files");}if(file.isEmpty()||file.getSize()>25L*1024*1024)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Replacement must be non-empty and at most 25 MB");String original=Objects.requireNonNullElse(file.getOriginalFilename(),"revised-evidence");String ext=extension(original);Path dir=storageDir();Files.createDirectories(dir);String storage=UUID.randomUUID()+"."+ext;Path dst=dir.resolve(storage);file.transferTo(dst);String oldHash=e.referenceHash;e.storageName=storage;e.filename=Path.of(original).getFileName().toString();e.mimeType=Objects.requireNonNullElse(file.getContentType(),"application/octet-stream");e.size=Files.size(dst);String newHash=ForensicsService.hash(dst);e.lastObservedHash=newHash;e.lastIntegrityStatus="INTACT";e.lastCheckedAt=Instant.now();evidence.save(e);recordVersion(e,a.getName(),Objects.requireNonNullElse(note,"Revised evidence file"));service.audit(a.getName(),"EVIDENCE_NEW_VERSION",e.evidenceNo,"SUCCESS","Original SHA-256 retained="+oldHash+"; new version SHA-256="+newHash+"; note="+note);if(!a.getName().equals(e.registeredBy))service.alert("HIGH","Evidence file changed by "+a.getName()+". Original SHA-256 remains preserved.",e.id,a.getName(),e.registeredBy);return versions.findByEvidenceIdOrderByVersionNumberDesc(e.id).get(0);}
 void blockedChange(Evidence e,Authentication a,String action){service.audit(a.getName(),action,e.evidenceNo,"BLOCKED","Unauthorized evidence modification attempt");service.alert("HIGH","Unauthorized change attempt by "+a.getName()+" on "+e.evidenceNo,e.id,a.getName(),e.registeredBy);}
 @GetMapping("/evidence/{id}/versions") List<Map<String,Object>> listVersions(@PathVariable long id,Authentication a){Evidence e=get(id);if(!canViewEvidence(e,a))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return versions.findByEvidenceIdOrderByVersionNumberDesc(id).stream().map(v->Map.<String,Object>of("id",v.id,"versionNumber",v.versionNumber,"sha256",v.sha256,"filename",v.filename,"changedBy",v.changedBy,"note",Objects.toString(v.note,""),"createdAt",v.createdAt)).toList();}
 @GetMapping("/evidence/{id}/versions/{versionId}/download") ResponseEntity<byte[]> downloadVersion(@PathVariable long id,@PathVariable long versionId,Authentication a)throws Exception{Evidence item=get(id);if(!canViewEvidence(item,a))throw new ResponseStatusException(HttpStatus.FORBIDDEN);EvidenceVersion version=versions.findById(versionId).filter(v->Objects.equals(v.evidenceId,id)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Evidence version not found"));Path file=storageDir().resolve(version.storageName).normalize();if(!file.startsWith(storageDir()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid evidence storage reference");service.audit(a.getName(),"EVIDENCE_VERSION_DOWNLOAD",item.evidenceNo,"SUCCESS","version="+version.versionNumber+"; sha256="+version.sha256);return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(version.filename,StandardCharsets.UTF_8).build().toString()).contentType(MediaType.APPLICATION_OCTET_STREAM).body(Files.readAllBytes(file));}
 long parse(String id){try{return Long.parseLong(id);}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid evidence id");}}
 @GetMapping("/evidence/{id}/download") ResponseEntity<byte[]> download(@PathVariable String id,Authentication a)throws Exception{Evidence e=get(parse(id));if(!canViewEvidence(e,a))throw new ResponseStatusException(HttpStatus.FORBIDDEN);Path p=storageDir().resolve(e.storageName);service.audit(a.getName(),"EVIDENCE_DOWNLOAD",e.evidenceNo,"SUCCESS","");return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+e.filename.replace("\"","")+"\"").contentType(MediaType.APPLICATION_OCTET_STREAM).body(Files.readAllBytes(p));}
 @PostMapping("/evidence/{id}/verify") Map<String,Object> verify(@PathVariable String id,Authentication a)throws Exception{if(role(a,"RECIPIENT"))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Read-only accounts can inspect integrity but cannot create verification records");Evidence e=get(parse(id));if(!canViewEvidence(e,a))throw new ResponseStatusException(HttpStatus.FORBIDDEN);Path p=storageDir().resolve(e.storageName);String observed;String status;try{observed=ForensicsService.hash(p);status=service.expectedHash(e).equals(observed)?"INTACT":"MODIFIED";}catch(Exception ex){observed="";status="VERIFICATION_ERROR";}Verification v=new Verification();v.evidenceId=e.id;v.actor=a.getName();v.referenceHash=e.referenceHash;v.currentVersionHash=service.expectedHash(e);v.observedHash=observed;v.status=status;v.createdAt=Instant.now();e.lastObservedHash=observed;e.lastIntegrityStatus=status;e.lastCheckedAt=v.createdAt;evidence.save(e);verifications.save(v);service.audit(a.getName(),"VERIFY",e.evidenceNo,status,"observed="+observed);if(!"INTACT".equals(status)){service.alert("HIGH","Evidence hash mismatch",e.id,a.getName(),e.registeredBy);}return Map.of("status",status,"referenceHash",e.referenceHash,"currentVersionHash",service.expectedHash(e),"observedHash",observed,"verifiedAt",v.createdAt);}
 @GetMapping("/evidence/{id}/integrity") Map<String,Object> readIntegrity(@PathVariable String id,Authentication a)throws Exception{Evidence e=get(parse(id));if(!canViewEvidence(e,a))throw new ResponseStatusException(HttpStatus.FORBIDDEN);try{String observed=ForensicsService.hash(storageDir().resolve(e.storageName));String status=service.expectedHash(e).equals(observed)?"INTACT":"MODIFIED";e.lastObservedHash=observed;e.lastIntegrityStatus=status;e.lastCheckedAt=Instant.now();evidence.save(e);if(!"INTACT".equals(status)){service.audit(a.getName(),"READ_ONLY_INTEGRITY_CHECK",e.evidenceNo,status,"Mismatch observed; no evidence bytes changed by this check");service.alert("HIGH","Integrity mismatch found during read-only check",e.id,a.getName(),e.registeredBy);}return Map.of("status",status,"referenceHash",e.referenceHash,"currentVersionHash",service.expectedHash(e),"observedHash",observed);}catch(Exception ex){return Map.of("status","VERIFICATION_ERROR","referenceHash",e.referenceHash,"observedHash","");}}
 @GetMapping("/verifications") List<Verification> verifications(Authentication a){return verifications.findAllByOrderByIdDesc().stream().filter(v->evidence.findById(v.evidenceId).map(e->canViewEvidence(e,a)).orElse(false)).toList();}
 @PostMapping("/custody") Custody requestTransfer(@RequestBody Map<String,String> b,Authentication a){Evidence e=get(parse(b.get("evidenceId")));boolean allowed=role(a,RolePolicy.ADMIN)||role(a,RolePolicy.INVESTIGATOR)&&cases.findAll().stream().filter(c->Objects.equals(c.caseNo,e.caseNo)).anyMatch(c->Objects.equals(c.assignedTo,a.getName()));if(!canViewEvidence(e,a)||!allowed)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the assigned investigator can request a custody transfer");UserRecord recipient=users.findByUsername(b.get("recipient")).filter(u->u.enabled&&Set.of(RolePolicy.ADMIN,RolePolicy.INVESTIGATOR).contains(u.role)).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Custody must be transferred to an active ADMIN or INVESTIGATOR account"));Custody c=new Custody();c.evidenceId=e.id;c.previousCustodian=e.custodian;c.fileHash=service.expectedHash(e);c.evidenceVersion=versions.findByEvidenceIdOrderByVersionNumberDesc(e.id).stream().findFirst().map(v->v.versionNumber).orElse(1);c.recipient=recipient.username;c.initiatedBy=a.getName();c.reason=b.get("reason");c.notes=b.get("notes");if(c.reason==null||c.reason.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Transfer reason is required");c.status="REQUESTED";c.requestedAt=Instant.now();custody.save(c);service.audit(a.getName(),"TRANSFER_REQUEST",e.evidenceNo,"SUCCESS","from="+c.previousCustodian+"; to="+c.recipient+"; reason="+c.reason);return c;}
 @PostMapping("/custody/{id}/respond") Custody respond(@PathVariable long id,@RequestBody Map<String,String>b,Authentication a){Custody c=custody.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!role(a,RolePolicy.ADMIN,RolePolicy.INVESTIGATOR)||!Objects.equals(c.recipient,a.getName()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the authorized investigator recipient can respond to this transfer");if(!"REQUESTED".equals(c.status))throw new ResponseStatusException(HttpStatus.CONFLICT,"This transfer has already been answered");String result=b.get("status");if(!Set.of("ACCEPTED","REJECTED").contains(result))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);c.status=result;c.respondedAt=Instant.now();if(result.equals("ACCEPTED")){Evidence e=get(c.evidenceId);e.custodian=a.getName();evidence.save(e);c.resultingCustodian=a.getName();}custody.save(c);service.audit(a.getName(),"TRANSFER_"+result,evidence.findById(c.evidenceId).map(x->x.evidenceNo).orElse(""),"SUCCESS","");return c;}
 @GetMapping("/custody") List<Custody> custody(Authentication a){return custody.findAll().stream().filter(c->role(a,"ADMIN")||c.initiatedBy.equals(a.getName())||c.recipient.equals(a.getName())||c.previousCustodian.equals(a.getName())).toList();}
 @GetMapping("/custody/recipients") List<Map<String,Object>> transferRecipients(Authentication a){if(!role(a,RolePolicy.ADMIN,RolePolicy.INVESTIGATOR))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return users.findAll().stream().filter(u->u.enabled&&Set.of(RolePolicy.ADMIN,RolePolicy.INVESTIGATOR).contains(u.role)).map(u->Map.<String,Object>of("username",u.username,"role",u.role)).toList();}
 @GetMapping("/evidence/{id}/custody") List<Custody> custodyFor(@PathVariable long id,Authentication a){Evidence e=get(id);if(!canViewEvidence(e,a))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return custody.findByEvidenceIdOrderByIdAsc(id);}
 @GetMapping("/evidence/{id}/timeline") List<Map<String,Object>> evidenceTimeline(@PathVariable long id,Authentication a){Evidence e=get(id);if(!canViewEvidence(e,a))throw new ResponseStatusException(HttpStatus.FORBIDDEN);List<Map<String,Object>> events=new ArrayList<>();events.add(timelineItem(e.uploadedAt,e.registeredBy,"EVIDENCE_REGISTERED","Evidence registered; original SHA-256="+e.referenceHash,0, e.referenceHash,null,null,"REGISTERED"));for(EvidenceVersion v:versions.findByEvidenceIdOrderByVersionNumberDesc(id))events.add(timelineItem(v.createdAt,v.changedBy,"EVIDENCE_VERSION","Version "+v.versionNumber+" submitted; reason: "+Objects.toString(v.note,"not provided"),v.versionNumber,v.sha256,null,null,"RECORDED"));for(Custody c:custody.findByEvidenceIdOrderByIdAsc(id)){events.add(timelineItem(c.requestedAt,c.initiatedBy,"CUSTODY_REQUEST","Transfer requested to "+c.recipient+"; reason: "+Objects.toString(c.reason,"not provided")+"; notes: "+Objects.toString(c.notes,""),c.evidenceVersion,c.fileHash,c.previousCustodian,c.recipient,c.status));if(c.respondedAt!=null)events.add(timelineItem(c.respondedAt,c.recipient,"CUSTODY_"+c.status,"Transfer "+c.status.toLowerCase(Locale.ROOT)+"; custodian remains "+Objects.toString(c.resultingCustodian,c.previousCustodian),c.evidenceVersion,c.fileHash,c.previousCustodian,c.resultingCustodian,c.status));}for(Verification v:verifications.findAllByOrderByIdDesc())if(Objects.equals(v.evidenceId,id))events.add(timelineItem(v.createdAt,v.actor,"INTEGRITY_"+v.status,"Integrity check "+v.status.toLowerCase(Locale.ROOT),0,v.observedHash,null,null,v.status));events.sort(Comparator.comparing(x->(Instant)x.get("at")));for(int i=0;i<events.size();i++)events.get(i).put("eventNumber",i+1);return events;}
 Map<String,Object> timelineItem(Instant at,String actor,String action,String details,int version,String hash,String previous,String next,String status){Map<String,Object> item=new LinkedHashMap<>();item.put("at",at);String identity=Objects.toString(actor,"SYSTEM");item.put("actor",identity);item.put("actorRole",users.findByUsername(identity).map(u->u.role).orElse("SYSTEM"));item.put("action",action);item.put("details",details);item.put("version",version);item.put("sha256",Objects.toString(hash,""));item.put("previousCustodian",Objects.toString(previous,""));item.put("newCustodian",Objects.toString(next,""));item.put("status",Objects.toString(status,""));return item;}
 @GetMapping("/audit") List<AuditEntry> audit(Authentication a){if(!role(a,RolePolicy.ADMIN,RolePolicy.AUDITOR))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return audits.findAllByOrderByIdAsc();}
 @GetMapping("/audit/verify") Map<String,Object> verifyAudit(Authentication a){if(!role(a,RolePolicy.ADMIN,RolePolicy.AUDITOR))throw new ResponseStatusException(HttpStatus.FORBIDDEN);String previous="0".repeat(64);for(AuditEntry x:audits.findAllByOrderByIdAsc()){try{String canonical=ForensicsService.auditCanonical(x.at,x.actor,x.action,x.target,x.outcome,x.details,previous);String calculated=ForensicsService.hex(java.security.MessageDigest.getInstance("SHA-256").digest(canonical.getBytes(StandardCharsets.UTF_8)));if(!previous.equals(x.previousHash)||!calculated.equals(x.entryHash)){service.audit(a.getName(),"AUDIT_CHAIN_VERIFY","audit:"+x.id,"FAILED","First invalid chain link found");service.alert("CRITICAL","Audit chain integrity check failed at entry "+x.id,null,a.getName(),a.getName());return Map.of("valid",false,"brokenAt",x.id);}previous=x.entryHash;}catch(Exception ex){return Map.of("valid",false,"brokenAt",x.id);}}long checked=audits.count();service.audit(a.getName(),"AUDIT_CHAIN_VERIFY","audit","SUCCESS","Verified "+checked+" entries");return Map.of("valid",true,"entries",checked);}
 @GetMapping("/alerts") List<AlertRecord> alerts(Authentication a){var u=users.findByUsername(a.getName()).orElseThrow();return alerts.findAllByOrderByIdDesc().stream().filter(x->u.role.equals("ADMIN")||a.getName().equals(x.owner)).toList();}
 @PutMapping("/alerts/{id}/read") AlertRecord read(@PathVariable long id,Authentication a){AlertRecord x=alerts.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!role(a,"ADMIN")&&!a.getName().equals(x.owner))throw new ResponseStatusException(HttpStatus.FORBIDDEN);x.unread=false;x.acknowledgedBy=a.getName();return alerts.save(x);}
 @DeleteMapping("/evidence/{id}") ResponseEntity<?> denyDelete(@PathVariable long id,Authentication a){Evidence e=get(id);service.audit(a.getName(),"DELETE_ATTEMPT",e.evidenceNo,"BLOCKED","Evidence retained");service.alert("HIGH","Blocked evidence deletion attempt",id,a.getName(),e.registeredBy);throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Evidence deletion is disabled; record preserved");}
 @GetMapping("/reports/evidence.csv") ResponseEntity<String> csv(Authentication a){if(!role(a,RolePolicy.ADMIN,RolePolicy.AUDITOR))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Evidence export is restricted to administrators and auditors");StringBuilder s=new StringBuilder("evidence_no,filename,category,case,sha256,custodian,status\n");for(Evidence e:evidence.findAll().stream().filter(item->canViewEvidence(item,a)).toList())s.append(row(e.evidenceNo)).append(',').append(row(e.filename)).append(',').append(row(e.category)).append(',').append(row(e.caseNo)).append(',').append(row(e.referenceHash)).append(',').append(row(e.custodian)).append(",REGISTERED\n");return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=evidence.csv").body(s.toString());}
 @GetMapping("/reports/cases.csv") ResponseEntity<String> casesCsv(Authentication a){requireReportRole(a);StringBuilder out=new StringBuilder("case_no,title,status,assigned_to,hearing_date,due_date\n");cases.findAll().stream().filter(c->canViewCase(c,a)).forEach(c->out.append(row(c.caseNo)).append(',').append(row(c.title)).append(',').append(row(c.status)).append(',').append(row(c.assignedTo)).append(',').append(row(Objects.toString(c.hearingDate,""))).append(',').append(row(Objects.toString(c.investigationDueDate,""))).append('\n'));return csvResponse("cases.csv",out);}
 @GetMapping("/reports/versions.csv") ResponseEntity<String> versionsCsv(Authentication a){requireReportRole(a);StringBuilder out=new StringBuilder("evidence_no,version,filename,sha256,changed_by,reason,created_at\n");versions.findAll().stream().filter(v->evidence.findById(v.evidenceId).filter(e->canViewEvidence(e,a)).isPresent()).forEach(v->{Evidence e=evidence.findById(v.evidenceId).orElseThrow();out.append(row(e.evidenceNo)).append(',').append(v.versionNumber).append(',').append(row(v.filename)).append(',').append(row(v.sha256)).append(',').append(row(v.changedBy)).append(',').append(row(v.note)).append(',').append(row(Objects.toString(v.createdAt,""))).append('\n');});return csvResponse("versions.csv",out);}
 @GetMapping("/reports/verifications.csv") ResponseEntity<String> verificationsCsv(Authentication a){requireReportRole(a);StringBuilder out=new StringBuilder("evidence_no,actor,status,original_sha256,current_version_sha256,observed_sha256,created_at\n");verifications.findAllByOrderByIdDesc().stream().filter(v->evidence.findById(v.evidenceId).filter(e->canViewEvidence(e,a)).isPresent()).forEach(v->{Evidence e=evidence.findById(v.evidenceId).orElseThrow();out.append(row(e.evidenceNo)).append(',').append(row(v.actor)).append(',').append(row(v.status)).append(',').append(row(v.referenceHash)).append(',').append(row(v.currentVersionHash)).append(',').append(row(v.observedHash)).append(',').append(row(Objects.toString(v.createdAt,""))).append('\n');});return csvResponse("verifications.csv",out);}
 @GetMapping("/reports/custody.csv") ResponseEntity<String> custodyCsv(Authentication a){requireReportRole(a);StringBuilder out=new StringBuilder("evidence_no,event_no,version,previous_custodian,recipient,actor,status,reason,notes,file_sha256,requested_at,responded_at\n");custody.findAll().stream().filter(c->evidence.findById(c.evidenceId).filter(e->canViewEvidence(e,a)).isPresent()).forEach(c->{Evidence e=evidence.findById(c.evidenceId).orElseThrow();out.append(row(e.evidenceNo)).append(',').append(c.id).append(',').append(c.evidenceVersion).append(',').append(row(c.previousCustodian)).append(',').append(row(c.recipient)).append(',').append(row(c.initiatedBy)).append(',').append(row(c.status)).append(',').append(row(c.reason)).append(',').append(row(c.notes)).append(',').append(row(c.fileHash)).append(',').append(row(Objects.toString(c.requestedAt,""))).append(',').append(row(Objects.toString(c.respondedAt,""))).append('\n');});return csvResponse("custody.csv",out);}
 @GetMapping("/reports/audit.csv") ResponseEntity<String> auditCsv(Authentication a){if(!role(a,RolePolicy.ADMIN,RolePolicy.AUDITOR))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Audit export is restricted to administrators and auditors");StringBuilder out=new StringBuilder("event_no,timestamp,actor,action,target,outcome,details,previous_hash,event_hash\n");audits.findAllByOrderByIdAsc().forEach(x->out.append(x.id).append(',').append(row(Objects.toString(x.at,""))).append(',').append(row(x.actor)).append(',').append(row(x.action)).append(',').append(row(x.target)).append(',').append(row(x.outcome)).append(',').append(row(x.details)).append(',').append(row(x.previousHash)).append(',').append(row(x.entryHash)).append('\n'));return csvResponse("audit.csv",out);}
 void requireReportRole(Authentication a){if(!role(a,RolePolicy.ADMIN,RolePolicy.AUDITOR))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Reports are restricted to administrators and auditors");}
 ResponseEntity<String> csvResponse(String name,StringBuilder body){return ResponseEntity.ok().contentType(MediaType.parseMediaType("text/csv;charset=UTF-8")).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename="+name).body(body.toString());}
 String row(String v){String x=Objects.toString(v,"");String leading=x.stripLeading();if(leading.startsWith("=")||leading.startsWith("+")||leading.startsWith("-")||leading.startsWith("@"))x="'"+x;return "\""+x.replace("\"","\"\"")+"\"";}
 boolean role(Authentication a,String... roles){return a!=null&&users.findByUsername(a.getName()).filter(u->u.enabled).map(u->Arrays.asList(roles).contains(u.role)).orElse(false);}
}
